window.LOGO = {w:1270,h:649,ink:"data:image/png;base64,",gold:"data:image/png;base64,"};
(function () {
  const load = src => { const i = new Image(); i.src = src; return i; };
  LOGO.inkImg = load(LOGO.ink); LOGO.goldImg = load(LOGO.gold);
  window.ASSETS_READY = Promise.all([LOGO.inkImg.decode(), LOGO.goldImg.decode()]);
})();
